"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[93995],{26876:e=>{e.exports=JSON.parse('{"id":"2026-08-07-viber-message-templates","date":"2026-08-07","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber message templates","excerpt":"You can now create and manage Viber message templates \u2014 pre-approved message formats for transactional messages and OTPs, with dynamic {{parameter}} placeholders substituted at send time. Creating templates requires an admin role on the account.","hasArticle":true,"bodyHtml":"<p>You can now create and manage <strong>Viber message templates</strong> \u2014 pre-approved message formats for transactional messages and OTPs, with dynamic <code>{{parameter}}</code> placeholders substituted at send time. Creating templates requires an admin role on the account.</p>\\n<h2>Two template categories</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>Category</th>\\n<th>Use for</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><strong>Transactional</strong></td>\\n<td>Order confirmations, shipping updates, appointment reminders.</td>\\n</tr>\\n<tr>\\n<td><strong>OTP</strong></td>\\n<td>One-time passwords and verification codes.</td>\\n</tr>\\n</tbody></table>\\n<h2>Create a template via the API</h2>\\n<pre><code class=\\"language-http\\">POST /api/v1/accounts/{accountId}/channels/{viberChannelId}/templates\\n</code></pre>\\n<p>The request body takes <code>name</code> (lowercase letters, numbers, and underscores), <code>category</code> (<code>Transactional</code> or <code>OTP</code>), <code>language</code> (e.g. <code>en</code>, <code>id</code>), and <code>text</code> with <code>{{parameter_name}}</code> placeholders for the dynamic parts.</p>\\n<h2>Full Viber channel docs</h2>\\n<p>This release also published the complete Viber channel documentation set \u2014 account onboarding, concepts &amp; fundamentals, sessions, billing, compliance, and the message API library.</p>\\n<ul>\\n<li><a href=\\"/connect/docs/viber-templates-management\\">Viber Templates Management guide</a></li>\\n<li><a href=\\"/connect/reference/add-viber-template\\">Add a Viber template \u2014 API reference</a></li>\\n<li><a href=\\"/connect/docs/viber/viber-hub\\">Viber hub</a></li>\\n</ul>\\n"}')}}]);